#include "native_helpers.hpp"
std::vector<P> audit(const J&base,size_t k){check_modulus(base);require(num(base.at("n"))==83&&num(base.at("a"))==1&&num(base.at("subgroup_order"))==8569786107849059ULL&&num(base.at("orbit_columns"))==k,"Base boundary mismatch");auto&raw=base.at("factor_base_point_coordinates").array;auto&labels=base.at("factor_base_point_labels").array;auto&reps=base.at("factor_base_representatives").array;require(reps.size()==k&&raw.size()==166*k&&labels.size()==raw.size(),"Base dimensions mismatch");std::vector<P> out;std::set<U> keys;for(size_t c=0;c<k;c++){auto rep=point(reps[c]);require(on(rep)&&mul(8569786107849059ULL,rep).inf&&keys.insert(orbit_key(rep)).second,"Invalid/duplicate representative");out.push_back(rep);auto p=rep;uint64_t coeff=1;for(int n=0;n<83;n++){for(int sign=0;sign<2;sign++){size_t i=166*c+2*n+sign;require(point(raw[i])==(sign?neg(p):p),"Base signed point mismatch");require(num(labels[i].at(0))==c&&num(labels[i].at(1))==(sign?8569786107849059ULL-coeff:coeff),"Base label mismatch");}p=tau(p);coeff=mm(coeff,2998004823950457ULL,8569786107849059ULL);}}return out;}
int main(int argc,char**argv){try{require(argc==6,"usage: check_candidates RETAINED WINDOW600 PREFIX1271 PREFIX1798 NEW_RECEIPT");std::vector<J>b;for(int i=1;i<5;i++)b.push_back(read_json(argv[i]));auto c0=audit(b[0],600),c2=audit(b[1],600),c3=audit(b[2],1271),c4=audit(b[3],1798);std::set<U>old;for(auto p:c0)old.insert(orbit_key(p));size_t overlap=0;for(size_t i=0;i<600;i++){require(c0[i]==c4[i]&&c2[i]==c4[600+i],"Candidate prefix/window recipe mismatch");overlap+=old.count(orbit_key(c2[i]));}require(overlap==0,"C2 must have disjoint support");for(size_t i=0;i<1271;i++)require(c3[i]==c4[i],"C3 prefix mismatch");std::ostringstream o;o<<"{\"kind\":\"n83_basis_candidates_audit\",\"status\":\"PASS\",\"retained_window_signed_orbit_overlap\":0,\"prefix_window_relations_verified\":true,\"candidates\":[";for(int i=0;i<4;i++){if(i)o<<",";o<<"{\"path\":"<<qstr(argv[i+1])<<",\"sha256\":"<<qstr(digest(argv[i+1]))<<",\"base_hash\":"<<qstr(b[i].at("base_hash").scalar)<<",\"columns\":"<<dec(num(b[i].at("orbit_columns")))<<"}";}o<<"],\"checker_source_sha256\":"<<qstr(digest(__FILE__))<<",\"checker_executable_sha256\":"<<qstr(digest(argv[0]))<<"}\n";create_new(argv[5],o.str());std::cout<<"PASS: exact bases, orbit labels, prefix/window recipes, disjoint C2 support\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
